-- Run after 20260821140000_add_project_glass_cost_quick_entry.sql.
select proname,pg_get_function_identity_arguments(oid) arguments,prosecdef security_definer from pg_proc where pronamespace='public'::regnamespace and proname in('create_project_glass_cost_entry','update_project_glass_cost_entry','void_project_glass_cost_entry') order by proname;
-- Before UAT, capture counts. Run create/update/void RPCs as an approved Admin, then compare.
select 'glass_cost_statements' table_name,count(*) row_count from public.glass_cost_statements union all select 'glass_cost_allocations',count(*) from public.glass_cost_allocations union all select 'glass_cost_allocation_history',count(*) from public.glass_cost_allocation_history;
select s.id,s.supply_amount_krw,a.project_id,a.allocated_supply_amount_krw,s.supply_amount_krw-a.allocated_supply_amount_krw unallocated,s.status statement_status,a.status allocation_status from public.glass_cost_statements s join public.glass_cost_allocations a on a.statement_id=s.id where (s.id,a.project_id)=(nullif(current_setting('app.verify_glass_statement_id',true),'')::uuid,nullif(current_setting('app.verify_project_id',true),'')::bigint);
select h.action,h.before_data,h.after_data,h.changed_at from public.glass_cost_allocation_history h where h.statement_id=nullif(current_setting('app.verify_glass_statement_id',true),'')::uuid order by h.changed_at;
select a.project_id,coalesce(sum(a.allocated_supply_amount_krw),0) actual_glass_cost_krw from public.glass_cost_allocations a join public.glass_cost_statements s on s.id=a.statement_id where a.status='active' and s.status='active' group by a.project_id;
-- Multi-project protection: update_project_glass_cost_entry and void_project_glass_cost_entry must raise 23514 when active allocation count is not one or the amount is not 100% allocated.
